/**
 * The window part. Every `view` exported here is a page the app can open; the
 * route is relative to the plugin, so this page is the plugin's home.
 */
import { useClient, useQuery, view } from "@tokamak/sdk/client";
// Generated by the build from src/server; commit it so the editor type-checks
// the page before the first build.
import { api } from "../server/_generated/api";

export const Hello = view({ route: "/", title: "Hello" }, () => {
  // useQuery calls the server function and keeps the result live: a reload of
  // the plugin re-runs it, so a changed message shows without restarting.
  const greeting = useQuery(useClient(), api.greeting.get, () => ({}));
  return (
    <section aria-label="Hello" class="flex flex-col gap-2 p-8">
      <h1 class="text-read font-semibold text-ink">Hello</h1>
      <p role="status" class="text-row text-ink-2">
        {greeting.loading() ? "Asking the server…" : greeting.data()?.text}
      </p>
      <p role="alert" class="text-row text-ink-3">
        {greeting.error()?.message}
      </p>
    </section>
  );
});
